#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class MinHeap {
    vector<int> data;
public:
    void push(int val) {
        data.push_back(val);
        int i = data.size() - 1;
        while (i > 0 && data[(i-1)/2] > data[i]) {
            swap(data[i], data[(i-1)/2]);
            i = (i-1)/2;
        }
    }
    int pop() {
        int min = data[0];
        data[0] = data.back();
        data.pop_back();
        int i = 0, n = data.size();
        while (true) {
            int smallest = i, l = 2*i+1, r = 2*i+2;
            if (l < n && data[l] < data[smallest]) smallest = l;
            if (r < n && data[r] < data[smallest]) smallest = r;
            if (smallest == i) break;
            swap(data[i], data[smallest]);
            i = smallest;
        }
        return min;
    }
    bool empty() const { return data.empty(); }
};

int main() {
    MinHeap h;
    for (int v : {5,3,8,1,9,2}) h.push(v);
    while (!h.empty()) cout << h.pop() << " ";
    cout << endl;
    return 0;
}
